var v = 343;
var vb = p.vb;
var vw = p.vw;
var f0 = p.f0 * 1000;
var f1 = f0 * (v + vw) / (v - vb);
var f2 = f1 * (v + vb) / (v - vw);

ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.lineWidth = 1;

var xB = W * 0.12;
var xW = W * 0.86;
var y0 = H * 0.46;

// wall
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(xW, y0 - 60);
ctx.lineTo(xW, y0 + 60);
ctx.stroke();
ctx.lineWidth = 1;
ctx.fillStyle = C.ink;
ctx.fillText('wall', xW - 12, y0 - 70);

// bat
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(xB, y0, 6, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText('bat', xB - 8, y0 - 16);

// motion arrows
function arrow(x, y, dx) {
  var s = dx > 0 ? 1 : -1;
  ctx.strokeStyle = C.figure;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x + dx, y);
  ctx.lineTo(x + dx - s * 5, y - 4);
  ctx.moveTo(x + dx, y);
  ctx.lineTo(x + dx - s * 5, y + 4);
  ctx.stroke();
}
if (vb > 0) arrow(xB + 10, y0 + 18, 22);
if (vw !== 0) arrow(xW - 10, y0 + 18, vw > 0 ? -22 : 22);

// outgoing crests (upper half), incoming crests (lower half)
var lamOut = Math.max((v - vb) / f0, 1e-6);
var lamIn = Math.max((v - vw) / f1, 1e-6);
var span = xW - xB - 18;
var nOut = 9;
var nIn = 9;
var phase = (t * 0.9) % 1;
var i, x;
ctx.strokeStyle = C.rule;
for (i = 0; i < nOut; i++) {
  x = xB + 14 + ((i + phase) / nOut) * span;
  ctx.beginPath();
  ctx.moveTo(x, y0 - 8);
  ctx.lineTo(x, y0 - 44);
  ctx.stroke();
}
for (i = 0; i < nIn; i++) {
  x = xW - 6 - ((i + phase) / nIn) * span;
  ctx.beginPath();
  ctx.moveTo(x, y0 + 8);
  ctx.lineTo(x, y0 + 44);
  ctx.stroke();
}

ctx.fillStyle = C.ink;
ctx.fillText('out: ' + (f0 / 1000).toFixed(1) + ' kHz leaves, ' + (f1 / 1000).toFixed(2) + ' kHz arrives at the wall', xB + 6, y0 - 52);
ctx.fillText('back: wall re-emits ' + (f1 / 1000).toFixed(2) + ' kHz, bat hears ' + (f2 / 1000).toFixed(2) + ' kHz', xB + 6, y0 + 62);

out.note = 'echo ' + f2.toFixed(1) + ' Hz against call ' + f0.toFixed(0) + ' Hz, beat ' + (f2 - f0).toFixed(1) + ' Hz';
